// Tiny DOM helpers: auto-escaping templates, toasts, bottom sheets.

const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
export const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ESC[c]);

class Raw { constructor(s) { this.s = s; } toString() { return this.s; } }
/** Mark trusted markup (already escaped / generated by us). */
export const raw = (s) => new Raw(s);

/** Tagged template: interpolations are escaped unless wrapped in raw() or arrays of html. */
export function html(strings, ...vals) {
  let out = '';
  strings.forEach((s, i) => {
    out += s;
    if (i < vals.length) out += render(vals[i]);
  });
  return new Raw(out);
}
function render(v) {
  if (v === null || v === undefined || v === false) return '';
  if (v instanceof Raw) return v.s;
  if (Array.isArray(v)) return v.map(render).join('');
  return esc(v);
}

export const $ = (sel, root = document) => root.querySelector(sel);
export const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

/** Delegate events: on(root, 'click', '[data-action=save]', (e, el) => …) */
export function on(root, type, selector, fn, opts) {
  const h = (e) => {
    const el = e.target.closest(selector);
    if (el && root.contains(el)) fn(e, el);
  };
  root.addEventListener(type, h, opts);
  return () => root.removeEventListener(type, h, opts);
}

export function toast(text, { kind = 'info', ms = 3200 } = {}) {
  const root = document.getElementById('toast-root');
  if (!root) return;
  const el = document.createElement('div');
  el.className = `toast toast-${kind}`;
  el.setAttribute('role', kind === 'error' ? 'alert' : 'status');
  el.textContent = text;
  root.appendChild(el);
  setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 300); }, ms);
}

let openSheets = 0;
/**
 * Open a bottom sheet / dialog. `build(body, close)` fills it.
 * Returns a promise resolving with the value passed to close().
 */
export function sheet({ title = '', className = '', label = title, dismissable = true } = {}, build) {
  return new Promise((resolve) => {
    const root = document.getElementById('overlay-root');
    const prevFocus = document.activeElement;
    const wrap = document.createElement('div');
    wrap.className = `sheet-wrap ${className}`;
    wrap.innerHTML = `<div class="sheet-backdrop" data-close></div>
      <div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(label)}">
        ${title ? `<div class="sheet-head"><h2 class="sheet-title">${esc(title)}</h2>${dismissable ? '<button class="icon-btn" data-close aria-label="Close">✕</button>' : ''}</div>` : ''}
        <div class="sheet-body"></div>
      </div>`;
    root.appendChild(wrap);
    openSheets++;
    document.body.classList.add('has-sheet');
    let done = false;
    const close = (value) => {
      if (done) return;
      done = true;
      wrap.classList.add('out');
      document.removeEventListener('keydown', onKey);
      setTimeout(() => {
        wrap.remove();
        if (--openSheets === 0) document.body.classList.remove('has-sheet');
        prevFocus?.focus?.();
      }, 180);
      resolve(value);
    };
    const onKey = (e) => {
      if (e.key === 'Escape' && dismissable) close(undefined);
    };
    document.addEventListener('keydown', onKey);
    if (dismissable) on(wrap, 'click', '[data-close]', () => close(undefined));
    const body = wrap.querySelector('.sheet-body');
    build(body, close);
    requestAnimationFrame(() => {
      wrap.classList.add('in');
      (wrap.querySelector('[autofocus]') || wrap.querySelector('.sheet button, .sheet input'))?.focus?.();
    });
  });
}

export function confirmSheet({ title, text, ok = 'OK', cancel = 'Cancel', danger = false }) {
  return sheet({ title }, (body, close) => {
    body.innerHTML = String(html`<p class="sheet-text">${text}</p>
      <div class="btn-row">
        <button class="btn ${danger ? 'btn-danger' : ''}" data-ok>${ok}</button>
        <button class="btn btn-ghost" data-cancel>${cancel}</button>
      </div>`);
    body.querySelector('[data-ok]').onclick = () => close(true);
    body.querySelector('[data-cancel]').onclick = () => close(false);
  });
}

export async function copyText(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    let ok = false;
    try { ok = document.execCommand('copy'); } catch { ok = false; }
    ta.remove();
    return ok;
  }
}
